feat:{n:'Featured Picks',tbl:'products',col:'pos_featured',key:'pf',min:0,list:()=>P.filter(p=>p.st==='approved'&&p.feat),note:'Products marked "Featured pick".'},
cat:{n:'Shop by Category',tbl:'categories',col:'home_order',key:'h',min:1,list:()=>C.filter(c=>c.h>0),note:'The category cards on the home page. Turn a category on or off in Categories.'},
exp:{n:'Explore Our Products',tbl:'products',col:'pos_explore',key:'pe',min:0,list:()=>P.filter(p=>p.st==='approved'&&p.exp),note:'Products you selected for Explore Our Products (and its Boys / Girls / Adults tabs).'},
best:{n:'Best Sellers',tbl:'products',col:'pos_best',key:'pb',min:0,list:()=>P.filter(p=>p.st==='approved'&&p.best),note:'Products marked "Best seller".'},
promo:{n:'Promo banners',tbl:'promo_banners',col:'sort',key:'sort',min:0,list:()=>PB,note:'Order of the banners under the hero buttons.'},
