const bt=$('[data-a="hsv"]');bt.disabled=true;const row={tag:$('#htag').value.trim(),title:tt,image:window._img,link_type:t,link_value:v};let r;
if(id!=='')r=await sb.from('hero_slides').update(row).eq('id',HS[+id].id);
